var computeBwip = (function () {
  var NAMES = {
    itf14: 'ITF-14', upce: 'UPC-E', code39: 'Code 39', codabar: 'Codabar',
    isbn: 'ISBN', databar: 'GS1 DataBar', gs1: 'GS1', maxicode: 'MaxiCode',
    microqr: 'Micro QR', datamatrix: 'Data Matrix', aztec: 'Aztec', pdf417: 'PDF417',
    'gs1-128': 'GS1-128', gs1datamatrix: 'GS1 Data Matrix',
  };

  // symbol key -> [BWIP export, bwip-js bcid]. The key is what lands in the
  // bcSymbology extra; `gs1` resolves to a key via the carrier select first.
  var ENCODERS = {
    itf14: ['itf14', 'itf14'],
    upce: ['upce', 'upce'],
    code39: ['code39', 'code39'],
    codabar: ['rationalizedCodabar', 'rationalizedCodabar'],
    isbn: ['isbn', 'isbn'],
    databar: ['databaromni', 'databaromni'],
    maxicode: ['maxicode', 'maxicode'],
    'gs1-128': ['gs1_128', 'gs1-128'],
    gs1datamatrix: ['gs1datamatrix', 'gs1datamatrix'],
    microqr: ['microqrcode', 'microqrcode'],
    datamatrix: ['datamatrix', 'datamatrix'],
    aztec: ['azteccode', 'azteccode'],
    pdf417: ['pdf417', 'pdf417'],
  };

  // The symbols drawn as bars with a human-readable line, which take the
  // barHeight/quiet/showText inputs. Everything else is a fixed-shape symbol.
  var LINEAR = { itf14: 1, upce: 1, code39: 1, codabar: 1, isbn: 1, databar: 1, 'gs1-128': 1 };

  function _esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function _hex(v, fb) {
    var s = (v == null ? '' : String(v)).trim().toLowerCase();
    var m3 = /^#?([0-9a-f])([0-9a-f])([0-9a-f])$/.exec(s);
    if (m3) return '#' + m3[1] + m3[1] + m3[2] + m3[2] + m3[3] + m3[3];
    var m6 = /^#?([0-9a-f]{6})$/.exec(s);
    return m6 ? '#' + m6[1] : fb;
  }

  function _num(v, fb, lo, hi) {
    var n = Number(v);
    if (!Number.isFinite(n)) n = fb;
    return Math.min(hi, Math.max(lo, n));
  }

  // Same greedy wrap + panel as the barcode IIFE: an unencodable value must show
  // words on the canvas, because onInit/onInput swallow hook errors.
  function _wrapLines(text, max) {
    var words = String(text).split(/\s+/);
    var lines = [];
    var line = '';
    for (var i = 0; i < words.length; i++) {
      if (!words[i]) continue;
      var next = line ? line + ' ' + words[i] : words[i];
      if (line && next.length > max) {
        lines.push(line);
        line = words[i];
      } else {
        line = next;
      }
    }
    if (line) lines.push(line);
    return lines;
  }

  function errorSvg(note, hint) {
    var lines = _wrapLines(note, 56);
    var body = '';
    var y = 140;
    for (var i = 0; i < lines.length; i++) {
      body += '<text x="300" y="' + (y + i * 26) + '" text-anchor="middle" font-family="sans-serif" '
        + 'font-size="17" fill="#111111">' + _esc(lines[i]) + '</text>';
    }
    var last = y + (lines.length - 1) * 26;
    if (hint) {
      last += 36;
      body += '<text x="300" y="' + last + '" text-anchor="middle" font-family="ui-monospace, Menlo, Consolas, monospace" '
        + 'font-size="17" fill="#111111">' + _esc(hint) + '</text>';
    }
    var h = Math.max(260, last + 60);
    return '<svg class="bc-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 ' + h + '" '
      + 'preserveAspectRatio="xMidYMid meet" role="img" aria-label="Code unavailable">'
      + '<rect x="0" y="0" width="600" height="' + h + '" rx="12" fill="#fff5f5"/>'
      + '<text x="300" y="96" text-anchor="middle" font-family="sans-serif" font-size="26" font-weight="700" fill="#bd3314">Code unavailable</text>'
      + body
      + '</svg>';
  }

  // GTIN-family modulo-10, identical maths to the EAN path's eanCheckDigit
  // (that copy is private to the computeBarcode IIFE).
  function _mod10(body) {
    var sum = 0;
    for (var i = body.length - 1, w = 3; i >= 0; i--, w = w === 3 ? 1 : 3) sum += Number(body.charAt(i)) * w;
    return (10 - (sum % 10)) % 10;
  }

  function _digits(raw) {
    return String(raw == null ? '' : raw).replace(/[\s-]/g, '');
  }

  // ─── Normalizers - { value } or { error, hint } ────────────────────────────
  // Forgiving on the way in (spaces/hyphens stripped, check digits worked out,
  // conventional wrappers added), strict on what gets encoded.

  function _normItf14(raw) {
    var d = _digits(raw);
    if (!d) return { error: 'Type the number this ITF-14 should carry.' };
    if (!/^[0-9]+$/.test(d)) return { error: 'ITF-14 holds digits only.' };
    if (d.length === 13) return { value: d + _mod10(d) };
    if (d.length !== 14) {
      return { error: 'ITF-14 needs 14 digits, or 13 to have the check digit worked out. This one has ' + d.length + '.' };
    }
    var want = _mod10(d.slice(0, 13));
    if (want !== Number(d.charAt(13))) {
      return {
        error: 'ITF-14 ends in a check digit, and this one does not match the rest of the number.',
        hint: 'Did you mean ' + d.slice(0, 13) + want + '?',
      };
    }
    return { value: d };
  }

  function _normUpce(raw) {
    var d = _digits(raw);
    if (!d) return { error: 'Type the number this UPC-E should carry.' };
    if (!/^[0-9]+$/.test(d)) return { error: 'UPC-E holds digits only.' };
    // 6 digits is how a UPC-E is usually read off a packet: number system 0
    // assumed, check digit worked out (by the encoder, on the expanded UPC-A).
    if (d.length === 6) return { value: '0' + d };
    if (d.length === 7 || d.length === 8) return { value: d };
    return { error: 'UPC-E needs 6, 7 or 8 digits. This one has ' + d.length + '.' };
  }

  function _normCode39(raw) {
    var text = String(raw == null ? '' : raw).trim().toUpperCase();
    if (!text) return { error: 'Type the text this Code 39 should carry.' };
    for (var i = 0; i < text.length; i++) {
      if (!/[0-9A-Z\-. $\/+%]/.test(text.charAt(i))) {
        return { error: 'Code 39 cannot hold "' + text.charAt(i) + '" (character ' + (i + 1) + '). It takes digits, capital letters, space and - . $ / + %.' };
      }
    }
    return { value: text };
  }

  function _codabarBadChar(text) {
    for (var i = 0; i < text.length; i++) {
      if (!/[0-9\-$:\/.+]/.test(text.charAt(i))) {
        return { error: 'Codabar cannot hold "' + text.charAt(i) + '" (character ' + (i + 1) + '). It takes digits and - $ : / . + between A-D start and stop letters.' };
      }
    }
    return { error: 'Codabar needs digits between its A-D start and stop letters.' };
  }

  function _normCodabar(raw) {
    var text = String(raw == null ? '' : raw).trim().toUpperCase();
    if (!text) return { error: 'Type the number this Codabar should carry.' };
    if (text.length >= 2 && /^[A-D]/.test(text) && /[A-D]$/.test(text)) {
      var body = text.slice(1, -1);
      if (!/^[0-9\-$:\/.+]*$/.test(body)) return _codabarBadChar(body);
      return { value: text };
    }
    // No start/stop letters typed: wrap the plain value in the conventional A...A.
    if (!/^[0-9\-$:\/.+]+$/.test(text)) return _codabarBadChar(text);
    return { value: 'A' + text + 'A' };
  }

  function _normIsbn(raw) {
    var text = String(raw == null ? '' : raw).trim().toUpperCase();
    if (!text) return { error: 'Type the ISBN this barcode should carry.' };
    // The registration-group hyphenation is not computable from the digits, so
    // a bare number is asked back rather than guessed at and printed wrong.
    if (/^[0-9]{9,12}[0-9X]$/.test(text)) {
      return { error: 'ISBN is typed with its dashes, the way it is printed on the book.', hint: 'Like 978-1-56581-231-4.' };
    }
    if (!/^[0-9X-]+$/.test(text)) return { error: 'ISBN holds digits and dashes only.' };
    return { value: text };
  }

  // The two fixed-length AIs everyone types by hand get the same "Did you mean"
  // the EAN path gives, instead of bwip-js's bare "Bad checksum".
  function _gs1Check(value) {
    var m = /^\((00|01)\)([0-9]*)(?=\(|$)/.exec(value);
    if (!m) return null;
    var len = m[1] === '00' ? 18 : 14;
    if (m[2].length !== len) return null;
    var body = m[2].slice(0, len - 1);
    var want = _mod10(body);
    if (want === Number(m[2].charAt(len - 1))) return null;
    return {
      error: 'AI (' + m[1] + ') ends in a check digit, and this one does not match the rest of the number.',
      hint: 'Did you mean (' + m[1] + ')' + body + want + value.slice(m[0].length) + '?',
    };
  }

  function _normGs1(raw) {
    var text = String(raw == null ? '' : raw).trim();
    if (!text) {
      return { error: 'Type the GS1 element string this code should carry.', hint: 'Like (01)09521234543213(17)270831(10)LOT42.' };
    }
    if (text.charAt(0) !== '(') {
      return { error: 'A GS1 element string starts with an AI in brackets.', hint: 'Like (01)09521234543213(17)270831(10)LOT42.' };
    }
    return _gs1Check(text) || { value: text };
  }

  function _normDatabar(raw) {
    var d = _digits(String(raw == null ? '' : raw).replace(/^\s*\(01\)/, ''));
    if (!d) return { error: 'Type the GTIN this GS1 DataBar should carry.', hint: 'Like (01)09521234543213.' };
    if (!/^[0-9]+$/.test(d)) return { error: 'GS1 DataBar carries a GTIN: digits only.' };
    if (d.length === 13) return { value: '(01)' + d + _mod10(d) };
    if (d.length !== 14) {
      return { error: 'GS1 DataBar carries a 14-digit GTIN, or 13 digits to have the check digit worked out. This one has ' + d.length + '.' };
    }
    var want = _mod10(d.slice(0, 13));
    if (want !== Number(d.charAt(13))) {
      return {
        error: 'A GTIN ends in a check digit, and this one does not match the rest of the number.',
        hint: 'Did you mean ' + d.slice(0, 13) + want + '?',
      };
    }
    return { value: '(01)' + d };
  }

  function _normMaxicode(raw) {
    var text = String(raw == null ? '' : raw).trim();
    if (!text) return { error: 'Type the text this MaxiCode should carry.' };
    return { value: text };
  }

  var NORMALIZERS = {
    itf14: _normItf14, upce: _normUpce, code39: _normCode39, codabar: _normCodabar,
    isbn: _normIsbn, gs1: _normGs1, databar: _normDatabar, maxicode: _normMaxicode,
  };

  // bwip-js errors read like "bwipp.GS1badChecksum#3251: AI 00: Bad checksum" -
  // keep the words, drop the machinery, and give the capacity failures a line
  // that says what to do about it.
  function _friendly(err, kindName) {
    var msg = (err && err.message) ? String(err.message) : String(err || '');
    msg = msg.replace(/^bwipp\.[A-Za-z0-9_]+#\d+:\s*/, '').replace(/^bwipp\.[A-Za-z0-9_]+:\s*/, '');
    if (/maximum length exceeded|invalid content|too long/i.test(msg)) {
      return 'Content is too long for a ' + kindName + ' - shorten it' + (kindName === 'Micro QR' ? ' or switch the shape back to QR.' : '.');
    }
    return msg || 'Could not build this ' + kindName + '.';
  }

  function _fail(note, hint, sym) {
    return {
      svgContent: errorSvg(note, hint),
      bgHex: '#fff5f5',
      inkHex: '#111111',
      bcError: note,
      bcHint: hint || '',
      bcSymbology: sym,
      bcValue: '',
      bcModules: '',
      bcSymbols: '',
      bcCheck: '',
      bcSummary: 'nothing yet',
      qrSummary: 'nothing yet',
    };
  }

  function computeCore(args) {
    var industrial = BWIP_BARCODES.indexOf(args.payload) >= 0;
    var sym;              // ENCODERS key = the bcSymbology extra
    var value;            // the text handed to the encoder
    var summary;
    var contentKind = '';
    var content = '';

    if (industrial) {
      var kind = args.payload;
      sym = kind === 'gs1' ? (args.gs1Carrier === 'gs1datamatrix' ? 'gs1datamatrix' : 'gs1-128') : kind;
      var norm = NORMALIZERS[kind](args.value);
      if (norm.error) return _fail(norm.error, norm.hint, sym);
      value = norm.value;
      summary = NAMES[sym] + ' ' + value;
    } else {
      contentKind = _KINDS.indexOf(args.payload) >= 0 ? args.payload : 'url';
      content = _payloadFor(args, contentKind);
      if (!content) return _fail(_KIND_HINT[contentKind] || 'Add some content for the code.', '', args.symbology);
      sym = args.symbology;
      value = content;
      summary = NAMES[sym] + ' holding ' + _summary(args, contentKind, content);
    }

    var pair = ENCODERS[sym];
    if (!pair) return _fail('Unknown code type "' + sym + '".', '', String(sym));

    var transparentBg = args.transparentBg === true;
    var background = _hex(args.background, '#ffffff');
    var color = _hex(args.color, '#111111');
    var linear = LINEAR[sym] === 1;

    var opts = { bcid: pair[1], text: value, barcolor: color };
    if (!transparentBg) opts.backgroundcolor = background;
    if (linear) {
      opts.includetext = args.showText !== false;
      opts.textcolor = color;
      // bwip-js bar heights are millimetres; the slider stays in canvas px,
      // mapped so the manifest default (160) lands on the 10 mm the specs draw.
      opts.height = _num(args.barHeight, 160, 40, 400) / 16;
      opts.paddingwidth = Math.round(_num(args.quiet, 11, 0, 24)) * 2;
      opts.paddingheight = 2;
    } else {
      // Quiet zone in module-ish steps: the industrial payloads reuse their
      // `quiet` slider, the content shapes their QR `padding` slider.
      var pad = industrial
        ? Math.round(_num(args.quiet, 11, 0, 24)) * 2
        : Math.round(_num(args.padding, 4, 0, 10)) * 4;
      opts.paddingwidth = pad;
      opts.paddingheight = pad;
      if (sym === 'maxicode') opts.mode = 4;
      if (sym === 'microqr') opts.eclevel = { L: 'L', M: 'M', Q: 'Q', H: 'Q' }[args.ecl] || 'M';
    }

    var svg;
    try {
      svg = BWIP[pair[0]](opts, BWIP.drawingSVG());
    } catch (err) {
      return _fail(_friendly(err, NAMES[sym] || 'code'), '', sym);
    }
    // bwip-js emits `<svg viewBox="..." xmlns="...">` with no width/height, so
    // it already scales to the canvas; add the same presentation attributes the
    // hand-rolled barcode SVG carries.
    svg = svg.replace('<svg ', '<svg class="bc-svg" role="img" aria-label="' + _esc(summary) + '" preserveAspectRatio="xMidYMid meet" ');

    var result = {
      svgContent: svg,
      bgHex: transparentBg ? 'transparent' : background,
      inkHex: color,
      bcError: '',
      bcHint: '',
      bcSymbology: sym,
      bcValue: value,
      bcModules: '',
      bcSymbols: '',
      bcCheck: '',
      bcSummary: summary,
      qrSummary: summary,
    };
    if (!industrial) {
      result.qrError = '';
      result.qrKind = contentKind;
      result.qrPayload = content;
    }
    return result;
  }

  // One-entry memo keyed on the whole args object, like the other two paths.
  var _memoKey = null;
  var _memoResult = null;

  return function (args) {
    _transparentBg = args.transparentBg === true;
    var key = JSON.stringify(args);
    if (key === _memoKey) return _memoResult;
    var result;
    try {
      result = computeCore(args);
    } catch (err) {
      result = _fail((err && err.message) ? err.message : 'Could not build this code', '', String(args.payload || ''));
    }
    _memoKey = key;
    _memoResult = result;
    return result;
  };
})();

// A throw in a payload builder must not reach the runtime: onInit/onInput
// swallow errors, so the canvas would go blank with nothing to read.
// Resolve a logo asset (plans/162 Part 3, WP-I) to an embeddable URL. The shells
// hand back a data: URI (see the CLI bridge), which inlines into the SVG's
// <image> and rasterises on export; a shell that can't returns '' and the tool
// simply renders no logo (progressive enhancement). Cached by id.
var _qbLogoCache = {};
async function _qbLogoUrl(val, host) {
  if (!val) return '';
  if (typeof val === 'object' && typeof val.url === 'string' && val.url) return val.url;
  var id = typeof val === 'string' ? val : (val && val.id);
  if (!id || typeof id !== 'string') return '';
  if (_qbLogoCache[id] != null) return _qbLogoCache[id];
  var url = '';
  try {
    if (host && host.assets && host.assets.get) {
      var f = await host.assets.get(id);
      if (f && typeof f.url === 'string') url = f.url;
    }
  } catch (e) { /* no logo, just the code */ }
  _qbLogoCache[id] = url;
  return url;
}

async function _run(model, host) {
  var args = Object.fromEntries(model.map(function(i) { return [i.id, i.value]; }));
  if (BARCODE_KINDS.indexOf(args.payload) >= 0) {
    args.symbology = args.payload;   // computeBarcode reads args.symbology (folded barcode, plans/147 T7a)
    return computeBarcode(args);
  }
  // The bwip-js route (plans/162): the industrial payloads, and any content
  // payload whose shape select asks for a 2D symbol other than QR.
  if (BWIP_BARCODES.indexOf(args.payload) >= 0) return computeBwip(args);
  if (MATRIX_SHAPES.indexOf(args.symbology) >= 0) return computeBwip(args);
  try {
    args._logoUrl = await _qbLogoUrl(args.logo, host);   // WP-I - '' when no logo/shell support
    var result = compute(args, host);
    // WP-K2: the generator consuming the reader. For a BRANDED code, rasterise
    // the finished SVG and ask host.scan to decode it - the belt to WP-K1's pure
    // validators. Progressive enhancement: absent host.scan/host.raster (CLI,
    // older shell) it is skipped, and it NEVER breaks the render (any failure of
    // our own returns 'unchecked', never a warning). compute() memoises, so we
    // clone before annotating.
    if (result && !result.qrError && result.svgContent && _qbIsBranded(args)) {
      var live = await _qbLiveScan(result.svgContent, result.qrPayload, host);
      if (live) {
        result = Object.assign({}, result, { qrLiveScan: live, qrLiveScanFail: live === 'fail' });
      }
    }
    return result;
  } catch (err) {
    var msg = (err && err.message) ? err.message : 'Could not generate QR code';
    return _fail(msg, _KINDS.indexOf(args.payload) >= 0 ? args.payload : 'url', '');
  }
}

function onInit({ model, host }) {
  return _run(model, host);
}

function onInput({ model, host }) {
  return _run(model, host);
}

function beforeExport({ format, opts }) {
  // Clear the container background for alpha-capable formats so the SVG's
  // fill:none background rect isn't composited onto an opaque canvas.
  var alphaFormats = ['png', 'webp', 'avif'];
  if (_transparentBg && alphaFormats.includes(format)) {
    opts.background = 'transparent';
  }
}
